export type PageOptions = {
  title: string;
  brand?: string;
  user?: { name: string; points: number; role: string } | null;
  error?: string | null;
  notice?: string | null;
  landing?: boolean;
};

export const LOGO_IMG = 'data:image/png;base64,';

const BASE_STYLE = `
:root { color-scheme: light;
  --bg: #ffffff; --fg: #0a0a0a; --surface: #ffffff; --border: #e4e4e7;
  --muted: #71717a; --brand: #0a0a0a; --on-brand: #ffffff; --brand-contrast: #ffffff;
  --danger-bg: #18181b; --danger-fg: #ffffff; --danger-border: #18181b;
  --ok-bg: #f4f4f5; --ok-fg: #18181b; --ok-border: #a1a1aa;
  --sidebar-bg: #f3f3f3; --sidebar-border: #d4d4d4; --paper-border: #0a0a0a;
  --paper-head: #e4e4e7; --paper-row-alt: #f3f3f3; }
body.public { --brand: #0a0a0a; --on-brand: #ffffff; --brand-contrast: #ffffff; }
* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body { margin: 0; font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  background: var(--bg); color: var(--fg); line-height: 1.5; }
.wrap { max-width: 42rem; margin: 0 auto; padding: 1.5rem; }
.card { background: var(--surface); border: 1px solid var(--border);
  border-radius: 0.75rem; padding: 1.25rem; margin-bottom: 1rem; }
h1 { font-size: 1.35rem; margin: 0 0 0.75rem; }
h2 { font-size: 1.05rem; margin: 0 0 0.5rem; }
h3 { font-size: 1rem; margin: 0 0 0.35rem; }
label { display: block; font-size: 0.875rem; font-weight: 600; margin: 0.75rem 0 0.25rem; }
input, select, textarea { width: 100%; padding: 0.55rem 0.7rem; border: 1px solid var(--border);
  border-radius: 0.5rem; font: inherit; background: var(--surface); color: var(--fg); }
button, .btn { display: inline-block; margin-top: 1rem; padding: 0.6rem 1.1rem; border: 0;
  border-radius: 0.5rem; background: var(--brand); color: var(--on-brand); font: inherit;
  font-weight: 600; cursor: pointer; text-decoration: none; }
button:disabled { opacity: 0.6; cursor: not-allowed; }
button.secondary, .btn.secondary { background: #3f3f46; color: #ffffff; }
.alert-error { background: var(--danger-bg); border: 1px solid var(--danger-border);
  color: var(--danger-fg); padding: 0.6rem 0.8rem; border-radius: 0.5rem;
  font-size: 0.9rem; font-weight: 600; }
.alert-ok { background: var(--ok-bg); border: 1px solid var(--ok-border); color: var(--ok-fg);
  padding: 0.6rem 0.8rem; border-radius: 0.5rem; font-size: 0.9rem; }
.muted { color: var(--muted); font-size: 0.875rem; }
.row { display: flex; gap: 1rem; flex-wrap: wrap; align-items: center; }
.pill { background: var(--brand); color: var(--on-brand); border-radius: 999px;
  padding: 0.1rem 0.6rem; font-size: 0.8rem; font-weight: 700; }
a { color: inherit; text-decoration: underline; text-underline-offset: 2px; }
nav.bottom a { margin-right: 1rem; color: var(--muted); text-decoration: none; font-size: 0.9rem; }
header.top { background: var(--surface); color: var(--fg); border-bottom: 1px solid var(--border); position: sticky; top: 0; z-index: 40; }
header.top .wrap { display: flex; align-items: center; justify-content: space-between;
  gap: 0.75rem; padding: 0.75rem 1.5rem; flex-wrap: wrap; max-width: 1366px; margin: 0 auto; }
header.top a { color: var(--fg); text-decoration: none; font-weight: 600; }
header.top .btn, header.top button { background: #ffffff; color: var(--fg); margin-top: 0;
  padding: 0.45rem 0.9rem; border: 1px solid var(--border); }
.brand { display: flex; align-items: center; gap: 0.5rem; }
.brand img { width: 28px; height: 28px; flex-shrink: 0; }
main.landing { max-width: 72rem; }
.hero { padding: 3.5rem 0 1rem; }
.hero h1 { font-size: clamp(2rem, 6vw, 3rem); line-height: 1.1; margin: 0 0 1rem;
  max-width: 22ch; }
.hero .lead { font-size: 1.15rem; color: var(--muted); max-width: 44rem; margin: 0 0 1.5rem; }
.cta-row { display: flex; gap: 0.75rem; flex-wrap: wrap; }
.cta-row .btn { margin-top: 0; }
.btn.lg { padding: 0.8rem 1.5rem; font-size: 1.05rem; }
.section { margin-top: 3.5rem; scroll-margin-top: 5.5rem; }
.section > h2 { font-size: 1.75rem; margin: 0 0 0.35rem; }
.section > .lead { color: var(--muted); margin: 0 0 1.25rem; max-width: 46rem; }
.grid { display: grid; gap: 1rem; grid-template-columns: repeat(auto-fit, minmax(15rem, 1fr)); }
.grid .card { margin-bottom: 0; }
.grid.plans { grid-template-columns: repeat(auto-fit, minmax(16rem, 1fr)); }
.feature p { margin: 0; color: var(--muted); font-size: 0.95rem; }
.plan { display: flex; flex-direction: column; }
.plan .pill { display: inline-block; margin-bottom: 0.5rem; align-self: flex-start; }
.plan.featured { border: 2px solid var(--fg); }
.plan .price { font-size: 2rem; font-weight: 700; margin: 0.5rem 0 0.75rem; }
.plan .price span { font-size: 0.9rem; font-weight: 500; color: var(--muted); }
.plan .features { margin-bottom: 1.25rem; }
.plan .btn { margin-top: auto; }
.features { list-style: none; padding: 0; margin: 0; }
.features li { padding: 0.5rem 0; border-top: 1px solid var(--border); font-size: 0.95rem; }
.features li:first-child { border-top: 0; }
.contact { max-width: 32rem; }
.contact textarea { resize: vertical; }
.foot { background: var(--surface); color: var(--fg); border-top: 1px solid var(--border); margin-top: 4rem; }
.foot .wrap { max-width: 1366px; margin: 0 auto; display: flex; gap: 0.75rem; align-items: center;
  justify-content: space-between; flex-wrap: wrap; padding-top: 1.25rem; padding-bottom: 1.25rem; }
.foot .muted { color: var(--muted); }
.home { display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:60vh;padding:2rem;text-align:center; }
.home-brand { margin-bottom:1.5rem; }
.home-brand img { width:180px;height:180px;object-fit:contain;display:block;margin:0 auto; }
.home-lead { color:var(--muted);font-size:1.15rem;margin-bottom:2rem;max-width:46rem; }
.home-cta { display:flex;gap:0.75rem;justify-content:center;flex-wrap:wrap; }
.home-cta .btn { padding:0.75rem 1.5rem;font-size:1rem; }
@media (max-width: 48rem) {
  .wrap { padding: 1rem; }
  header.top .wrap { padding: 0.65rem 1rem; }
  .home { min-height:50vh; padding:1rem; }
  .home-lead { font-size:1rem; }
  .section { margin-top: 2.5rem; }
  .section > h2 { font-size: 1.4rem; }
  .foot .wrap { justify-content: flex-start; }
}

/* --- Barra lateral (admin / store_manager) --- */
.sidebar { position: fixed; top: 0; left: 0; width: 210px; height: 100vh;
  background: var(--sidebar-bg); border-right: 1px solid var(--sidebar-border);
  padding-top: 1rem; padding-bottom: 1rem; overflow-y: auto; z-index: 50;
  transition: transform 0.25s ease; }
@media (max-width: 768px) {
  .sidebar { transform: translateX(-100%); }
  .sidebar.open { transform: translateX(0); }
}
.sidebar .sid-brand { padding: 0.75rem 1rem; font-weight: 800; font-size: 1.05rem;
  color: var(--fg); border-bottom: 1px solid var(--sidebar-border); margin-bottom: 0.5rem; }
.sidebar a.sid-brand:hover { background: transparent; }
.sidebar .sid-user { padding: 0.75rem 1rem; font-size: 0.8rem; color: var(--muted);
  border-bottom: 1px solid var(--sidebar-border); margin-bottom: 0.75rem; }
.sidebar a { display: block; padding: 0.6rem 1rem; color: var(--fg); text-decoration: none;
  border-radius: 0.4rem; margin-bottom: 0.2rem; font-size: 0.9rem; }
.sidebar a.active { background: var(--fg); color: #ffffff; }
.sidebar a:hover { background: var(--sidebar-border); }
.sidebar .sep { height: 1px; background: var(--sidebar-border); margin: 0.5rem 0; }
.sidebar .sid-foot { padding: 0.75rem 1rem; font-size: 0.75rem; color: var(--muted);
  border-top: 1px solid var(--sidebar-border); margin-top: 0.75rem; }

.sidebar-overlay { position: fixed; top: 0; left: 0; width: 100%; height: 100vh;
  background: rgba(0,0,0,0.3); z-index: 49; opacity: 0; visibility: hidden;
  transition: opacity 0.25s ease; }
.sidebar-overlay.open { opacity: 1; visibility: visible; }

.hamburger { display: none; position: fixed; top: 0.6rem; left: 0.75rem; z-index: 45;
  background: var(--surface); border: 1px solid var(--border); border-radius: 0.5rem;
  padding: 0.45rem; cursor: pointer; color: var(--fg); }
.hamburger svg { width: 24px; height: 24px; }

.layout-sidebar { margin-left: 210px; padding: 1rem 1.5rem; min-width: 0; }

@media (max-width: 768px) {
  .hamburger { display: block; }
  .sidebar { width: 260px; }
  .sidebar-overlay.open { opacity: 1; visibility: visible; }
  .layout-sidebar { margin-left: 0; padding: 3.5rem 1rem 1rem; }
  header.top .wrap { padding: 0.75rem 1rem; }
  main { margin-left: 0; }
  .cta-row { flex-direction: column; width: 100%; }
  .cta-row .btn { width: 100%; }
  .grid { grid-template-columns: 1fr; }
  .grid.plans { grid-template-columns: 1fr; }
  table.papel { font-size: 0.8rem; }
  table.papel th, table.papel td { padding: 0.4rem 0.5rem; }
  .btn.lg { width: 100%; }
  .home-cta { flex-direction: column; width: 100%; }
  .home-cta .btn { width: 100%; }
}

/* --- Tablas tipo papel (formularios de estación) --- */
table.papel { width: 100%; border-collapse: collapse; border: 2px solid var(--paper-border); }
table.papel th { background: var(--paper-head); border: 1px solid var(--paper-border);
  padding: 0.5rem 0.75rem; font-weight: 700; text-align: left; font-size: 0.8rem;
  text-transform: uppercase; letter-spacing: 0.05em; color: var(--fg); }
table.papel td { border: 1px solid var(--paper-border); padding: 0.5rem 0.75rem;
  font-size: 0.9rem; vertical-align: top; }
table.papel td.num { text-align: right; font-variant-numeric: tabular-nums; }
table.papel tr:nth-child(even) td { background: var(--paper-row-alt); }
table.papel .seccion { background: var(--paper-head); font-weight: 700;
  text-transform: uppercase; letter-spacing: 0.05em; font-size: 0.8rem; }

/* --- Secciones tipo formulario impreso --- */
.seccion-papel { border: 1px solid var(--paper-border); padding: 1rem; margin-bottom: 1rem;
  background: var(--surface); page-break-inside: avoid; }
.seccion-papel h2 { background: var(--paper-head); padding: 0.5rem 0.75rem;
  margin: -1rem -1rem 1rem -1rem; font-size: 0.9rem; text-transform: uppercase;
  letter-spacing: 0.05em; border-bottom: 1px solid var(--paper-border); }
.campo-subrayado { border: none; border-bottom: 1px solid var(--paper-border);
  padding: 0.25rem 0.4rem; font-size: 1rem; background: transparent; color: var(--fg);
  width: 100%; }
.campo-subrayado:focus { outline: none; border-bottom-color: var(--fg); }
.linea-firma { border-bottom: 1px solid var(--paper-border); height: 1.2rem; }
.cabecera-papel { border: 2px solid var(--paper-border); padding: 0.75rem 1rem;
  margin-bottom: 1rem; background: var(--surface); }
.cabecera-papel h1 { font-size: 1.25rem; margin: 0; text-transform: uppercase;
  letter-spacing: 0.08em; }
.cabecera-papel .sub { font-size: 0.85rem; color: var(--muted); margin-top: 0.25rem; }
`;

const AUTH_STYLE = `body { --brand: #eb7716; --on-brand: #ffffff; --brand-contrast: #eb7716; }`;

function esc(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

export function escapeHtml(value: string): string {
  return esc(value);
}

export function page(opts: PageOptions, body: string): string {
  const brand = opts.brand ?? 'LESCO GNC';
  const alerts = [
    opts.error ? `<div class="alert-error">${esc(opts.error)}</div>` : '',
    opts.notice ? `<div class="alert-ok">${esc(opts.notice)}</div>` : '',
  ].join('');

  const footer = opts.landing
    ? `<footer class="foot"><div class="wrap">
  <span class="brand"><img src="${LOGO_IMG}" alt="LESCO GNC" style="width:36px;height:36px;flex-shrink:0;display:block"><span>${esc(brand)}</span></span>
  <span class="muted">© ${new Date().getFullYear()} ${esc(brand)}. Todos los derechos reservados.</span>
</div></footer>`
    : '';

  const head = `<!doctype html>
<html lang="es-AR">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${esc(opts.title)} · ${esc(brand)}</title>
<style>${BASE_STYLE}${opts.user ? AUTH_STYLE : ''}</style>
</head>
<body${opts.user ? '' : ' class="public"'}> `;

  if (opts.user && opts.user.role !== 'customer') {
    return head +
      `<div class="sidebar-overlay" id="sidebarOverlay"></div>
      <button class="hamburger" id="hamburger" aria-label="Menú" aria-expanded="false"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="3" y1="6" x2="21" y2="6"></line><line x1="3" y1="12" x2="21" y2="12"></line><line x1="3" y1="18" x2="21" y2="18"></line></svg></button>
      <aside class="sidebar" id="sidebar">
        <a class="sid-brand" href="/"><img src="${LOGO_IMG}" alt="${esc(brand)}" style="width:36px;height:36px;flex-shrink:0;display:block"><span style="margin-left:0.25rem;font-size:0.9rem">${esc(brand)}</span></a>
        <div class="sid-user">${esc(opts.user.name)} · ${esc(opts.user.role)}</div>
        ${sidebarLinks(opts.user)}
        <div class="sep"></div>
        <div class="sid-foot"><form method="post" action="/logout" style="margin:0"><button class="btn secondary" style="width:100%;padding:0.5rem 0.7rem;font-size:0.85rem">Cerrar sesión</button></form></div>
      </aside>
      <main class="layout-sidebar">
        ${alerts}
        ${body}
        ${footer}
      </main>
      <script>
        (function(){
          const sidebar = document.getElementById('sidebar');
          const overlay = document.getElementById('sidebarOverlay');
          const hamburger = document.getElementById('hamburger');
          if (!sidebar || !overlay || !hamburger) return;
          function open(){ sidebar.classList.add('open'); overlay.classList.add('open'); hamburger.setAttribute('aria-expanded','true'); document.body.style.overflow='hidden'; }
          function close(){ sidebar.classList.remove('open'); overlay.classList.remove('open'); hamburger.setAttribute('aria-expanded','false'); document.body.style.overflow=''; }
          hamburger.addEventListener('click', function(){ sidebar.classList.contains('open') ? close() : open(); });
          overlay.addEventListener('click', close);
          document.addEventListener('keydown', function(e){ if(e.key==='Escape') close(); });
          document.querySelectorAll('.sidebar a[href]').forEach(function(a){ a.addEventListener('click', close); });
        })();
      </script>` +
      `</body></html>`;
  }

  if (opts.user) {
    const nav = headerNav(opts);
    return head +
      `<header class="top"><div class="wrap">
        <a class="brand" href="/"><img src="${LOGO_IMG}" alt="LESCO GNC" style="width:36px;height:36px;flex-shrink:0;display:block"><span>${esc(brand)}</span></a>
        ${nav}
      </div></header>
      <main class="wrap${opts.landing ? ' landing' : ''}">
      ${alerts}
      ${body}
      </main>
      ${footer}
      </body></html>`;
  }

  return head +
    `<header class="top"><div class="wrap">
      <a class="brand" href="/"><img src="${LOGO_IMG}" alt="LESCO GNC" style="width:36px;height:36px;flex-shrink:0;display:block"><span>${esc(brand)}</span></a>
      ${headerNav(opts)}
    </div></header>
    <main class="wrap${opts.landing ? ' landing' : ''}">
    ${alerts}
    ${body}
    </main>
    ${footer}
    </body></html>`;
}

function headerNav(opts: PageOptions): string {
  if (opts.user) {
    return `<div class="row">
        <a href="/app">Inicio</a>
        <a href="/ranking">Ranking</a>
        <a href="/tienda">Tienda</a>
        <a href="/perfil">Tu perfil</a>
        <form method="post" action="/logout" style="display:inline">
          <button class="secondary" style="margin-top:0;padding:0.35rem 0.7rem">Cerrar sesión</button>
        </form>
      </div>`;
  }
  if (opts.landing) {
    return `<nav class="row">
        <a href="#incluye">Qué incluye</a>
        <a href="#precios">Precios</a>
        <a href="#contacto">Contacto</a>
        <a href="/login">Accedé</a>
        <a class="btn" href="/registro">Creá tu cuenta</a>
      </nav>`;
  }
  return `<div class="row"><a href="/login">Accedé</a><a href="/registro">Creá tu cuenta</a></div>`;
}

function sidebarLinks(user: { name: string; points: number; role: string }): string {
  const role = user.role;
  const isAdmin = role === 'admin';
  const isGestor = role === 'store_manager';

  const items: { href: string; label: string }[] = isAdmin
    ? [
        { href: '/app', label: 'Inicio' },
        { href: '/admin/usuarios', label: 'Usuarios' },
        { href: '/admin/tiendas', label: 'Tiendas' },
        { href: '/admin/desafios', label: 'Desafíos' },
        { href: '/admin/ordenes', label: 'Órdenes' },
        { href: '/operativa', label: 'Operativa' },
        { href: '/ranking', label: 'Ranking' },
      ]
    : isGestor
      ? [
          { href: '/app', label: 'Inicio' },
          { href: '/tienda', label: 'Mi tienda' },
          { href: '/operativa', label: 'Operativa' },
          { href: '/admin/ordenes', label: 'Órdenes' },
          { href: '/ranking', label: 'Ranking' },
        ]
      : [];

  return items
    .map(
      (i) => `<a href="${i.href}">${esc(i.label)}</a>`,
    )
    .join('');
}
